@startuml

enum PriorityScore {
  HIGH
  LOW
}

class HospitalHouseMD {}

class Patient {
  + ConsentSigned : boolean
}

class Doctor {
  + Name : string
}

class Nurse {
  + Name : string
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

class Diagnosis {
  + Description : string
}

class Treatment {
  + Stage : int
}

class ConsentForm {
  + SignedDate : date
}

HospitalHouseMD "1" -- "*" Patient
HospitalHouseMD "1" -- "*" Doctor
HospitalHouseMD "1" -- "*" Nurse
HospitalHouseMD "1" -- "*" Illness

Patient "1" -- "1..*" Doctor : assigned to
Patient "1" -- "0..*" Diagnosis : has
Patient "1" -- "0..*" Treatment : undergoes
Patient "1" -- "0..1" ConsentForm : signs

Doctor "1" -- "0..*" Diagnosis : makes
Doctor "1" -- "0..*" Treatment : manages

Nurse "1" -- "0..*" Treatment : checks
Doctor "1" -- "0..*" Treatment : checks

Illness "1" -- "0..*" Diagnosis : causes
Illness "1" -- "0..*" Treatment : has possible

@enduml

